SELECT SM.sku_id, SM.sku_name, SM.sku_description, SM.category_id, SM.sku_price, SM.sale_count, CASE WHEN SM.sku_total_stock_count - SM.sale_count - COALESCE(SD.sale_count,0) != SM.sku_stock_count THEN -1 ELSE SM.sku_total_stock_count - SM.sale_count - COALESCE(SD.sale_count,0) END AS sku_stock_count
FROM sku_master SM LEFT JOIN sku_detail SD ON SM.sku_id = SD.sku_id WHERE SM.sku_status = 1 AND SM.is_deleted = 0 AND SM.sku_id IN
#{skuId,jdbcType=BIGINT}
